def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    if not cwd.startswith('/') or cwd != '/' and cwd.endswith('/'):
        return None

    # Start with cwd if path is relative, otherwise start with '/'
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        if link_count > max_links:
            return None

        # Split remaining path into components
        components = remaining.split('/')

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            # Append component to current path
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if candidate is a symlink
            if candidate in links:
                link_count += 1
                if link_count > max_links:
                    return None

                # Resolve the symlink target
                target = links[candidate]

                # If target is absolute, start from root
                if target.startswith('/'):
                    current = '/'
                    remaining = target[1:]
                else:
                    # Target is relative to the directory containing the link
                    if candidate == '/':
                        current = '/'
                    else:
                        current = candidate.rsplit('/', 1)[0]
                    remaining = target

                # Break out of component loop to process remaining components
                break
            else:
                # Not a symlink, just update current
                current = candidate
        else:
            # We processed all components without encountering a symlink
            break

    # Remove trailing slash (except for '/')
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

